def solve(tokens):
    """Evaluate reverse Polish notation with +, -, *, / (division truncates toward zero)."""
    if not tokens:
        raise ValueError("empty RPN expression")
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError("invalid RPN expression")
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:
                if b == 0:
                    raise ZeroDivisionError("division by zero in RPN expression")
                # Integer division truncated toward zero (works for arbitrarily large ints).
                q = abs(a) // abs(b)
                stack.append(q if (a >= 0) == (b >= 0) else -q)
        else:
            stack.append(int(tok))
    if len(stack) != 1:
        raise ValueError("invalid RPN expression")
    return stack[0]

