def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is an iterable of at least two elements representing
    ``[start, end]``.  Meetings with ``start > end`` are ignored.  A meeting
    may start exactly when the previous one ends.
    """
    if not meetings:
        return 0
    intervals = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue  # skip malformed entries
        # consider only valid intervals where start <= end
        if s <= e:
            intervals.append((s, e))
    # Greedy selection by earliest finishing time
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in intervals:
        if s >= last_end:
            count += 1
            last_end = e
    return count

