def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Expects an iterable of integers (e.g., list). For non‑iterable or unsupported
    types returns 0. Uses patience sorting (O(n log n)).
    """
    # Validate input type
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # Ensure x is comparable (int/float). If not, skip it.
        try:
            # Find position where x should be placed (first >= x)
            i = bisect.bisect_left(tails, x)
        except TypeError:
            # Incomparable element; ignore it
            continue
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

