    Resolve '.' and '..' components, collapse multiple slashes, and remove any
    trailing slash (except for the root).  The input is guaranteed to start with
    a '/' and represent an absolute path.
    """
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            # Skip empty segments caused by consecutive slashes and current dir.
            continue
        if segment == '..':
            # Move up one directory if possible.
            if parts:
                parts.pop()
            # If parts empty we are at root; stay there.
        else:
            parts.append(segment)
    # Reconstruct the canonical path.
    return '/' + '/'.join(parts) if parts else '/'

