def solve(s):
    """Run‑length encode *s*.
    *s* may be any iterable (including strings, lists, tuples, etc.). If *s* is
    falsy or not iterable, an empty list is returned.
    The result is a list of ``[element, count]`` pairs for each maximal run
    of equal consecutive elements.
    """
    # Guard against None or non‑iterable inputs.
    if not s:
        return []
    try:
        iterator = iter(s)
    except TypeError:
        return []
    result = []
    try:
        first = next(iterator)
    except StopIteration:
        return []
    prev = first
    count = 1
    for elem in iterator:
        if elem == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = elem
            count = 1
    result.append([prev, count])
    return result

