def solve(meetings):
    """Maximum number of non‑overlapping meetings.
    Handles malformed entries gracefully: skips items that are not indexable
    with at least two elements or whose start/end are not numbers.
    """
    # Prepare list of (start, end) as floats for reliable comparison
    intervals = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue
        try:
            s_val = float(s)
            e_val = float(e)
        except Exception:
            continue
        intervals.append((s_val, e_val))
    if not intervals:
        return 0
    # Sort by end, then start
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in intervals:
        if s >= last_end:
            count += 1
            last_end = e
    return count

