def solve(n, edges):
    """Return the lexicographically smallest topological ordering of nodes 0..n-1.
    edges is a list of [a, b] meaning a -> b. If a cycle exists, return [] .
    """
    # Validate n
    try:
        n_int = int(n)
    except Exception:
        return []
    if n_int <= 0:
        return []
    # Build graph
    adj = [[] for _ in range(n_int)]
    indeg = [0] * n_int
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            continue
        a, b = e
        if 0 <= a < n_int and 0 <= b < n_int:
            adj[a].append(b)
            indeg[b] += 1
    # Use min-heap for smallest available node
    import heapq
    heap = [i for i in range(n_int) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != n_int:
        return []
    return order

