def solve(n, edges):
    """Lexicographically smallest topological order for nodes 0..n-1.
    Returns [] if the graph has a cycle or inputs are invalid.
    """
    # Validate n
    try:
        n_int = int(n)
    except Exception:
        return []
    if n_int < 0:
        return []
    # Validate edges container
    if not isinstance(edges, (list, tuple)):
        return []
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n_int)]
    indeg = [0] * n_int
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            continue
        a, b = e
        if not (isinstance(a, int) and isinstance(b, int)):
            continue
        if 0 <= a < n_int and 0 <= b < n_int:
            adj[a].append(b)
            indeg[b] += 1
    # Kahn's algorithm with a min‑heap to guarantee smallest lexical order
    import heapq
    heap = [i for i in range(n_int) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    # If we couldn't process all nodes, a cycle exists
    if len(order) != n_int:
        return []
    return order

