import bisect
def solve(a, x):
    """Return the leftmost insertion index for *x* in sorted sequence *a*.
    Uses ``bisect_left`` which works for any sequence supporting ``__getitem__``
    and ``len``. If *a* is not a sequence (or is ``None``) an empty list is
    assumed, returning ``0``.
    """
    try:
        # ``bisect_left`` expects a list; if ``a`` is not a list/tuple it still
        # works as long as it implements ``__len__`` and ``__getitem__``.
        return bisect.bisect_left(a, x)
    except Exception:
        return 0

def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z. Handles negative n with a leading '-'.
    Returns an empty string for invalid inputs (non‑int n or b out of range).
    """
    # Validate and coerce inputs
    try:
        n_int = int(n)
        b_int = int(b)
    except Exception:
        return ''
    if b_int < 2 or b_int > 36:
        return ''
    # Zero is a special case
    if n_int == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n_int < 0
    n_abs = -n_int if neg else n_int
    res_chars = []
    while n_abs > 0:
        n_abs, rem = divmod(n_abs, b_int)
        res_chars.append(digits[rem])
    if neg:
        res_chars.append('-')
    return ''.join(reversed(res_chars))

