def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is given as a two‑element sequence (list/tuple) ``[start, end]``.
    If ``start`` > ``end`` we treat it as ``[end, start]``.
    A meeting may start exactly when another ends.
    """
    if not meetings:
        return 0
    # Normalise intervals and ensure they are tuples for faster access
    norm = []
    for m in meetings:
        # Accept any iterable of length 2
        try:
            s, e = m[0], m[1]
        except Exception:
            # Invalid meeting representation – skip
            continue
        if s <= e:
            norm.append((s, e))
        else:
            norm.append((e, s))
    # Greedy by earliest finishing time, then by start to break ties
    norm.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -10**18
    for start, end in norm:
        if start >= last_end:
            count += 1
            last_end = end
    return count

